import time
from threading import Thread

from ..config import abstract_core_logger_wrapper as logger_wrapper


def stop_keep_reservation_thread(thread, join=True):
    """
    Stop thread
    :param thread: Thread
    """
    thread.keep_going = False
    if join:
        thread.join()


class KeepReservationUeThread(Thread):
    """Keep Reservation checkr thread for reserved UEs monitoring and prolonging reservation."""

    def __init__(self, timeout, ue, logger):
        """

        :param timeout: float: Timeout
        :param ue: LteUe: UE object
        :param logger: Logger
        """
        self.timeout = timeout
        self.ue = ue
        self.last_keep_reservation_time = time.time()
        self.keep_going = True
        self._calm_period = timeout / 3.0
        self.logger = logger
        self.keep_going_feedback = False
        super().__init__(name=f"UeThread-{self.ue.alias}")

    def run(self):
        """Run keep reservation (UE) thread"""
        self.keep_going_feedback = True
        try:
            self.logger.debug(f"{self.ue.alias} - UeThread run start")
            self._run_taking_care()
        except Exception as e:  # pylint: disable=broad-except
            self.logger.debug("exception in _run_taking_care, it should never happened, " + str(e), exc_info=True)
        finally:
            self.logger.debug(f"{self.ue.alias} - UeThread run finish with success")
            self.keep_going = False
            self.keep_going_feedback = False

    def _run_taking_care(self):  # noqa: C901
        while self.keep_going and self.ue.reserved:
            actual_duration = time.time() - self.last_keep_reservation_time
            if actual_duration > self._calm_period:
                try:
                    self.logger.debug(f"{self.ue.alias} - prolonging..")
                    self.last_keep_reservation_time = time.time()
                    self.ue.keep_reservation()
                    self.last_keep_reservation_time = time.time()
                    self.logger.debug(f"{self.ue.alias} - prolonging reservation - ok")
                except Exception as exc:
                    self.logger.exception(exc)
            time.sleep(1.0)


class KeepReservationThread(Thread):
    """Keep Reservation check thread for reserved UEs monitoring and prolonging reservation."""

    def __init__(self, care_step_time):
        """

        :param care_step_time: Period value every which validation of all UEs from `ues` is checked
        """
        self.ues = {}
        self.care_step_time = care_step_time
        self.keep_going = True
        self.soft_stop = False
        self.logger = logger_wrapper.create_logger('thread-MAIN', 'ute_ue.keep_reservation.log')
        super().__init__(name="KeepReservationThread")

    def run(self):
        """Run keep reservation (MAIN) thread"""
        try:
            self.logger.debug("MAIN - Thread run start")
            self._run_taking_care()
        except Exception as e:  # pylint: disable=broad-except
            self.logger.debug("exception in _run_taking_care, it should never happened, " + str(e), exc_info=True)
        finally:
            self.logger.debug("MAIN - Thread run finally finish")

    def _run_taking_care(self):  # noqa: C901
        to_remove = []
        while self.keep_going:
            to_remove.clear()
            for ue_alias, ue_thread in self.ues.items():
                if not ue_thread.ue.reserved or not ue_thread.keep_going:
                    self.logger.debug(f"{ue_thread.ue.alias} - ue is not reserved - stopping thread")
                    ue_thread.keep_going = False
                    to_remove.append(ue_alias)
            for ue_alias in to_remove:
                if not self.ues[ue_alias].is_alive() and not self.ues[ue_alias].keep_going:
                    self.ues.pop(ue_alias)
            if not self.keep_going:
                break
            if len([ue for ue in self.ues.values() if ue.keep_going]) == 0 and self.soft_stop:
                break
            time.sleep(self.care_step_time)


class KeepReservation:
    """Keep Reservation singleton class for taf.ue plugins for robot_api instance."""

    def __init__(self):
        self.main_thread = None
        self.timeout = 200

    def start_keep_reservation(self, ue, timeout=None):
        """
        Start keep reservation
        :param ue: LteUe: UE object
        :param timeout: float: Timeout
        """
        ue_alias = ue.alias
        if not timeout or timeout < 30.0:
            self.timeout = 30.0
            self.main_thread.logger.warn(f"{ue.alias} - Timeout is too low, setting to minimal allowed value: "
                                         f"{self.timeout}")
        else:
            self.timeout = timeout
        try:
            ue.rpc_client.start_keep_reservation_ue(ue_id=ue.get_ue_id(), timeout=self.timeout)
        except Exception:
            return False
        if ue_alias:
            self.main_thread.ues[ue_alias] = KeepReservationUeThread(timeout=self.timeout, ue=ue,
                                                                     logger=self.main_thread.logger)
            if self.main_thread.ues[ue_alias].keep_going:
                self.main_thread.ues[ue_alias].start()
                self.main_thread.logger.debug(f"{ue_alias} - UeThread started")
                return True
        return False

    def stop_keep_reservation(self, ue_alias: str):
        """
        Stop keep reservation
        :param ue_alias: UE ID
        """
        if ue_alias and ue_alias in self.main_thread.ues:
            for alias, ue_thread in self.main_thread.ues.items():
                if ue_alias == alias:
                    ue_thread.ue.reserved = False
                    stop_keep_reservation_thread(ue_thread)
                    break

    def await_ue_thread_stopped(self, ue_alias: str):
        """
        Wait until specific thread is stopped
        :param ue_alias: UE ID
        """
        if ue_alias in self.main_thread.ues:
            while self.main_thread.ues[ue_alias].keep_going_feedback:
                time.sleep(0.5)

    def await_ue_threads_stopped(self):
        """
        Wait until all UE threads are ready
        """
        self.main_thread.logger.debug("MAIN - await all UE threads finished..")
        while any(ue_thread.keep_going_feedback for ue_thread in self.main_thread.ues.values()):
            time.sleep(0.5)

    def init_thread(self, period=1.0):
        """
        Init main thread
        """
        self.main_thread = KeepReservationThread(period)
        self.main_thread.start()
        while not self.main_thread.is_alive():
            time.sleep(0.5)

    def cancel_thread(self, *args, **kwargs):
        """
        Cancel main thread
        """
        if self.main_thread and self.main_thread.keep_going:
            self.main_thread.logger.debug("MAIN - cancel requested..")
            for ue_alias, ue_thread in self.main_thread.ues.items():
                ue_thread.keep_going = False
            for ue_alias, ue_thread in self.main_thread.ues.items():
                self.main_thread.logger.debug(f"{ue_alias} - stop thread..")
                stop_keep_reservation_thread(ue_thread, join=False)
            for ue_alias, ue_thread in self.main_thread.ues.items():
                if ue_thread.ue.reserved:
                    ue_thread.ue.reserved = False
                    self.main_thread.logger.debug(f"{ue_thread.ue.alias} - unset 'reserved' flag")
            self.main_thread.logger.debug("MAIN - all UE threads are finished", exc_info=True)
            self.main_thread.soft_stop = True
            stop_keep_reservation_thread(self.main_thread)
            self.main_thread.logger.debug("MAIN - end with success")
